from pathlib import Path
from zipfile import ZipFile,ZIP_DEFLATED
from html import escape
W='http://schemas.openxmlformats.org/wordprocessingml/2006/main'
R='http://schemas.openxmlformats.org/officeDocument/2006/relationships/'
out=Path(__file__).resolve().parents[1]/'public/fixtures'
BASE={'[Content_Types].xml': '<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/word/document.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml"/><Override PartName="/word/settings.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.settings+xml"/><Override PartName="/word/styles.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.styles+xml"/></Types>', '_rels/.rels': '<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rDoc" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="word/document.xml"/></Relationships>', 'word/_rels/document.xml.rels': '<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rSettings" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/settings" Target="settings.xml"/><Relationship Id="rStyles" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles" Target="styles.xml"/></Relationships>', 'word/settings.xml': '<w:settings xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main"><w:compat><w:compatSetting w:name="compatibilityMode" w:uri="http://schemas.microsoft.com/office/word" w:val="15"/></w:compat></w:settings>', 'word/styles.xml': '<w:styles xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main"><w:docDefaults><w:rPrDefault><w:rPr><w:rFonts w:ascii="Times New Roman" w:hAnsi="Times New Roman"/><w:sz w:val="32"/></w:rPr></w:rPrDefault></w:docDefaults><w:style w:type="paragraph" w:styleId="POn"><w:name w:val="POn"/><w:rPr><w:caps/></w:rPr></w:style><w:style w:type="character" w:styleId="COn"><w:name w:val="COn"/><w:rPr><w:caps/></w:rPr></w:style><w:style w:type="character" w:styleId="COff"><w:name w:val="COff"/><w:rPr><w:caps w:val="0"/></w:rPr></w:style><w:style w:type="paragraph" w:styleId="PLinked"><w:name w:val="PLinked"/><w:link w:val="CLinked"/><w:rPr><w:caps/></w:rPr></w:style><w:style w:type="character" w:styleId="CLinked"><w:name w:val="CLinked"/><w:link w:val="PLinked"/><w:rPr><w:caps/></w:rPr></w:style><w:style w:type="paragraph" w:styleId="PPlainLinked"><w:name w:val="PPlainLinked"/><w:link w:val="CPlainLinked"/><w:rPr></w:rPr></w:style><w:style w:type="character" w:styleId="CPlainLinked"><w:name w:val="CPlainLinked"/><w:link w:val="PPlainLinked"/><w:rPr><w:caps/></w:rPr></w:style><w:style w:type="character" w:styleId="CBase"><w:name w:val="CBase"/><w:rPr><w:caps/></w:rPr></w:style><w:style w:type="character" w:styleId="CChild"><w:name w:val="CChild"/><w:basedOn w:val="CBase"/><w:rPr><w:caps/></w:rPr></w:style><w:style w:type="paragraph" w:styleId="Title"><w:name w:val="Title"/><w:link w:val="TitleChar"/><w:rPr><w:caps/></w:rPr></w:style><w:style w:type="character" w:styleId="TitleChar"><w:name w:val="TitleChar"/><w:link w:val="Title"/><w:rPr><w:caps/></w:rPr></w:style><w:style w:type="paragraph" w:styleId="PSmall"><w:name w:val="PSmall"/><w:rPr><w:smallCaps/></w:rPr></w:style><w:style w:type="character" w:styleId="CSmall"><w:name w:val="CSmall"/><w:rPr><w:smallCaps/></w:rPr></w:style></w:styles>'}
for fmt in ['lowerRoman','upperRoman','lowerLetter']:
 parts=BASE.copy()
 paras=[]
 for i,(style,direct) in enumerate([('',''),('','<w:caps/>'),('','<w:smallCaps/>'),('POn',''),('PSmall','')],1):
  ppr=(f'<w:pStyle w:val="{style}"/>' if style else '')+'<w:spacing w:before="0" w:after="0" w:line="600" w:lineRule="exact"/>'
  def run(text):return '<w:r><w:rPr>'+direct+'</w:rPr><w:t xml:space="preserve">'+escape(text)+'</w:t></w:r>'
  complexfield='<w:r><w:fldChar w:fldCharType="begin"/></w:r><w:r><w:instrText> PAGE </w:instrText></w:r><w:r><w:fldChar w:fldCharType="separate"/></w:r>'+run('1')+'<w:r><w:fldChar w:fldCharType="end"/></w:r>'
  simple='<w:fldSimple w:instr=" PAGE ">'+run('i')+'</w:fldSimple>'
  locked='<w:fldSimple w:instr=" PAGE " w:fldLock="1">'+run('mix')+'</w:fldSimple>'
  paras.append('<w:p><w:pPr>'+ppr+'</w:pPr>'+run(f'C{i} text mix: ')+complexfield+run(' simple: ')+simple+run(' locked: ')+locked+run(' complex: ')+complexfield.replace('w:fldCharType="begin"','w:fldCharType="begin" w:fldLock="1"')+run(' counts: ')+locked.replace(' PAGE ',' NUMPAGES ')+run('/')+locked.replace(' PAGE ',' SECTIONPAGES ')+run(' |')+'</w:p>')
 parts['word/header.xml']=f'<w:hdr xmlns:w="{W}">'+''.join(paras)+'</w:hdr>'
 parts['word/document.xml']=f'<w:document xmlns:w="{W}" xmlns:r="{R[:-1]}"><w:body><w:p><w:r><w:t>Body one</w:t></w:r></w:p><w:p><w:pPr><w:pageBreakBefore/></w:pPr><w:r><w:t>Body two</w:t></w:r></w:p><w:sectPr><w:headerReference w:type="default" r:id="rHeader"/><w:pgSz w:w="12240" w:h="15840"/><w:pgMar w:top="4800" w:bottom="1440" w:left="720" w:right="720" w:header="720" w:footer="720" w:gutter="0"/><w:pgNumType w:fmt="{fmt}"/></w:sectPr></w:body></w:document>'
 parts['[Content_Types].xml']=parts['[Content_Types].xml'].replace('</Types>','<Override PartName="/word/header.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.header+xml"/></Types>')
 parts['word/_rels/document.xml.rels']=parts['word/_rels/document.xml.rels'].replace('</Relationships>',f'<Relationship Id="rHeader" Type="{R}header" Target="header.xml"/></Relationships>')
 with ZipFile(out/f'page-field-caps-{fmt}.docx','w',ZIP_DEFLATED) as z:
  for n,s in parts.items():z.writestr(n,s)
